===== node_teww.conf (nginx) =====
# Managed by Claude (originally aaPanel-generated). Three server blocks:
#   1) HTTP   :80   teww.org + www.teww.org    → 301 to https://teww.org
#                   (with /.well-known/ exception for ACME http-01 challenges)
#   2) HTTPS  :443  www.teww.org               → 301 to https://teww.org
#   3) HTTPS  :443  teww.org                   → proxy to Nest at 127.0.0.1:3001
#
# Cert: /etc/letsencrypt/live/teww.org/  (SAN: teww.org, www.teww.org)
# Renewal: certbot.timer (twice daily). aaPanel's own acme client no longer
# manages this domain since the cert path moved out of /www/server/panel/.

# 1) HTTP → HTTPS redirect (keeps /.well-known/ on plaintext for ACME).
server {
    listen 80;
    server_name teww.org www.teww.org;

    location /.well-known/ {
        root /www/wwwroot/teww.org;
    }

    location / {
        return 301 https://teww.org$request_uri;
    }
}

# 2) Canonical: www → apex over HTTPS.
server {
    listen 443 ssl http2;
    server_name www.teww.org;

    #SSL-START SSL related configuration
    ssl_certificate     /etc/letsencrypt/live/teww.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/teww.org/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;
    #SSL-END

    return 301 https://teww.org$request_uri;
}

# 3) Main site.
server {
    listen 443 ssl http2;
    server_name teww.org;
    index index.html index.htm default.htm default.html;

    #SSL-START SSL related configuration
    ssl_certificate     /etc/letsencrypt/live/teww.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/teww.org/privkey.pem;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-CHACHA20-POLY1305:DHE-RSA-AES128-GCM-SHA256:DHE-RSA-AES256-GCM-SHA384;
    ssl_prefer_server_ciphers off;
    ssl_session_cache shared:SSL:10m;
    ssl_session_timeout 10m;
    error_page 497 https://$host$request_uri;
    #SSL-END

    # Security headers (apply uniformly to API + static SPA).
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;
    add_header X-Frame-Options          "DENY" always;
    add_header X-Content-Type-Options   "nosniff" always;
    add_header Referrer-Policy          "strict-origin-when-cross-origin" always;
    add_header Permissions-Policy       "camera=(), microphone=(self), geolocation=()" always;

    # Outermost upload cap (Nest MediaController enforces per-kind limits inside).
    client_max_body_size 100m;

    #REWRITE-START Pseudo-static related configuration
    include /www/server/panel/vhost/rewrite/node_teww.conf;
    #REWRITE-END

    # Files or directories forbidden to access.
    location ~ ^/(\.user.ini|\.htaccess|\.git|\.svn|\.project|LICENSE|README.md|package.json|package-lock.json|\.env|node_modules) {
        return 404;
    }

    # ACME http-01 webroot path (kept here for safety, though HTTPS isn't required).
    location /.well-known/ {
        root /www/wwwroot/teww.org;
    }

    # Single upstream — Nest serves /api/* and the static SPA from one process.
    location / {
        proxy_pass http://127.0.0.1:3001;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header REMOTE-HOST $remote_addr;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_connect_timeout 30s;
        proxy_read_timeout 86400s;
        proxy_send_timeout 30s;
    }

    access_log /www/wwwlogs/teww.log;
    error_log  /www/wwwlogs/teww.error.log;
}

