#!/usr/bin/env bash
# Rolling staging deploy of the v1 branch -> stagingv1.teww.org.
# Also self-heals TLS: issues the cert and upgrades the vhost to HTTPS as soon
# as DNS for the host points at this VPS. No-ops when nothing changed.
set -euo pipefail
D=/www/wwwroot/stagingv1
HOST=stagingv1.teww.org
IP=147.93.134.216
WEB_PORT=3004
API_PORT=4001
ACME=/www/wwwroot/stagingv1-acme
VHOST=/www/server/panel/vhost/nginx/node_stagingv1.conf
export PATH=/www/server/nodejs/v24.15.0/bin:$PATH

write_vhost() {
  local https=$1 tmp; tmp=$(mktemp)
  {
    echo "# Managed by Claude. $HOST -> web :$WEB_PORT, /api/* -> :$API_PORT"
    echo "server {"
    echo "    listen 80;"
    echo "    server_name $HOST;"
    echo "    location /.well-known/acme-challenge/ { root $ACME; }"
    if [ "$https" = yes ]; then
      echo '    location / { return 301 https://$host$request_uri; }'
      echo "}"
      echo "server {"
      echo "    listen 443 ssl http2;"
      echo "    server_name $HOST;"
      echo "    ssl_certificate     /etc/letsencrypt/live/$HOST/fullchain.pem;"
      echo "    ssl_certificate_key /etc/letsencrypt/live/$HOST/privkey.pem;"
      echo "    ssl_protocols TLSv1.2 TLSv1.3;"
    fi
    cat <<PROXY
    client_max_body_size 50m;
    location /api/ {
        proxy_pass http://127.0.0.1:$API_PORT/;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400s;
    }
    location / {
        proxy_pass http://127.0.0.1:$WEB_PORT;
        proxy_http_version 1.1;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header Upgrade \$http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_read_timeout 86400s;
    }
    access_log /www/wwwlogs/stagingv1.log;
    error_log  /www/wwwlogs/stagingv1.error.log;
}
PROXY
  } > "$tmp"
  if ! cmp -s "$tmp" "$VHOST" 2>/dev/null; then
    mv "$tmp" "$VHOST"; nginx -t >/dev/null 2>&1 && nginx -s reload && echo "vhost updated (https=$https)"
  else rm -f "$tmp"; fi
}

# 1. deploy if v1 moved
cd "$D"
BEFORE=$(git rev-parse HEAD)
git fetch origin -q
REMOTE=$(git rev-parse origin/v1)
if [ "$BEFORE" != "$REMOTE" ]; then
  echo "[$(date -u +%FT%TZ)] v1 $BEFORE -> $REMOTE"
  git reset --hard "$REMOTE" -q
  pnpm install --frozen-lockfile
  NEXT_PUBLIC_API_URL=https://$HOST/api pnpm --filter web build
  pm2 restart stagingv1-api stagingv1-web --update-env >/dev/null
  echo "[$(date -u +%FT%TZ)] deployed $(git log --oneline -1)"
fi

# 2. TLS bootstrap once DNS points here
if [ ! -d "/etc/letsencrypt/live/$HOST" ]; then
  if getent hosts "$HOST" 2>/dev/null | grep -q "$IP"; then
    write_vhost no
    if certbot certonly --webroot -w "$ACME" -d "$HOST" --non-interactive --agree-tos --keep-until-expiring >/dev/null 2>&1; then
      echo "[$(date -u +%FT%TZ)] cert issued for $HOST"
    fi
  else
    write_vhost no   # serves over HTTP the moment DNS lands
  fi
fi
[ -d "/etc/letsencrypt/live/$HOST" ] && write_vhost yes || true
SCRIPT
