chmod +x /usr/local/bin/update-stagingv1.sh
TMP=$(mktemp); crontab -l 2>/dev/null | grep -v 'update-stagingv1.sh' > "$TMP" || true
echo '*/2 * * * * flock -n /tmp/deploy-stagingv1.lock /usr/local/bin/update-stagingv1.sh >> /var/log/deploy-stagingv1.log 2>&1' >> "$TMP"
crontab "$TMP"; rm -f "$TMP"
